587	      shouldProceed: false,
588	      failure: {
589	        cause: error,
590	        context:
591	          typeof error === "object" && error !== null
592	            ? getSupabaseErrorTelemetry({
593	                error,
594	                prefix: "proposeSyncError",
595	              })
596	            : undefined,
597	      },
598	    };
599	  }
