const getNodeExtraData = (
  node_uid: string,
): {
  author_local_id: string;
  created: string;
  last_modified: string;
  page_uid: string;
  /* eslint-enable @typescript-eslint/naming-convention */
} => {
  const result = window.roamAlphaAPI.q(
    `[
    :find
      ?author_uid
      ?page_uid
      ?created
      ?last_modified
      :in $ ?block_uid
      :where
      [?block :block/uid ?block_uid]
      [?block :create/user ?author_id]
